      if (f.id === 'tone' || f.id === 'want' || slotIds(x, f).length) return;   // 「这一幕想要」是让事情发生的，不随
      var pool = visOpts(f).filter(function (o) { return lewd || (o.tier || 0) < 2; });
      if (!pool.length) return;
