    statusHtml() +
    '<div class="fx-tabs">' + [['def', '🎛️ 定制'], ['spice', '🧂 加料'], ['cards', '🎬 剧情'], ['set', '⚙️']].map(function (t) { return '<button class="' + (tab === t[0] ? 'on' : '') + '" data-tab="' + t[0] + '">' + t[1] + '</button>'; }).join('') + '</div>' +
    '<div class="fx-body">' + (tab === 'def' ? defHtml() : tab === 'cards' ? cardsHtml() : tab === 'set' ? setHtml() : spiceHtml()) + '</div>';
